CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  product_id INTEGER
);

CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  customer TEXT,
  order_date DATE,
  amount INTEGER
);

solution:
SELECT customer, strftime('%Y-%m', order_date) AS month, AVG(amount) AS avg_monthly_spend
FROM orders
GROUP BY customer, month;

schema_sql:
CREATE TABLE book_sales (
  sale_id INTEGER,
  genre TEXT,
  sale_date DATE,
  quantity INTEGER
);

solution:
WITH monthly_sales AS (
  SELECT strftime('%Y-%m', sale_date) AS month, genre, SUM(quantity) AS total
  FROM book_sales
  GROUP BY month, genre
)
SELECT month, genre, total
FROM (
  SELECT *, RANK() OVER (PARTITION BY month ORDER BY total DESC) AS rnk
  FROM monthly_sales
) WHERE rnk = 1;

schema_sql:
CREATE TABLE volunteer_hours (
  name TEXT,
  city TEXT,
  hours INTEGER
);

solution:
SELECT name, city, hours FROM (
  SELECT *, RANK() OVER (PARTITION BY city ORDER BY hours DESC) AS rnk
  FROM volunteer_hours
) WHERE rnk = 1;

