schema_sql:
CREATE TABLE complaints (
  id INTEGER,
  category TEXT,
  comment TEXT
);

CREATE TABLE newsletter_history (
  email TEXT,
  status TEXT
);

solution:
SELECT DISTINCT email
FROM newsletter_history
WHERE email IN (
  SELECT email FROM newsletter_history WHERE status = 'Unsubscribed'
) AND email NOT IN (
  SELECT email FROM newsletter_history WHERE status = 'Subscribed'
  AND email NOT IN (
    SELECT email FROM newsletter_history WHERE status = 'Unsubscribed'
  )
);

